package com.aos.statusbar;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{
 int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
 TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(17,22,31));getWindow().setNavigationBarColor(Color.rgb(17,22,31));getWindow().getDecorView().setSystemUiVisibility(0);
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(32),dp(24),dp(24));root.setBackgroundColor(Color.rgb(14,18,25));
 TextView brand=label("AOS",38,Color.WHITE);brand.setTypeface(null,Typeface.BOLD);root.addView(brand);TextView sub=label("LIQUID GLASS • STATUS BAR",12,Color.rgb(150,174,205));sub.setLetterSpacing(.12f);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.bottomMargin=dp(28);root.addView(sub,sp);
 LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(18),dp(18),dp(18),dp(18));card.setBackgroundColor(Color.rgb(29,37,49));TextView ct=label("SETUP",12,Color.rgb(150,174,205));ct.setTypeface(null,Typeface.BOLD);card.addView(ct);TextView desc=label("Enable these permissions to bring the AOS glass status bar over your screen.",15,Color.WHITE);LinearLayout.LayoutParams dp1=new LinearLayout.LayoutParams(-1,-2);dp1.topMargin=dp(8);dp1.bottomMargin=dp(16);card.addView(desc,dp1);root.addView(card);
 Button a=btn("01   •   Grant overlay permission");a.setOnClickListener(v->{if(!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));else Toast.makeText(this,"Overlay permission already granted",0).show();});addButton(root,a);
 Button n=btn("02   •   Notification access");n.setOnClickListener(v->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS")));addButton(root,n);
 Button s=btn("03   •   Start AOS status bar");s.setTextColor(Color.WHITE);s.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(63,111,170)));s.setOnClickListener(v->{if(Settings.canDrawOverlays(this)){if(Build.VERSION.SDK_INT>=26)startForegroundService(new Intent(this,OverlayService.class));else startService(new Intent(this,OverlayService.class));Toast.makeText(this,"AOS status bar started",0).show();}else Toast.makeText(this,"Grant overlay permission first",0).show();});addButton(root,s);
 TextView foot=label("AOS  •  CUSTOM ANDROID EXPERIENCE",10,Color.rgb(100,115,135));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,-2);fp.topMargin=dp(28);root.addView(foot,fp);setContentView(root);}
 Button btn(String text){Button b=new Button(this);b.setText(text);b.setTextSize(13);b.setAllCaps(false);b.setTextColor(Color.rgb(230,238,249));b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(35,45,59)));return b;}
 void addButton(LinearLayout l,Button b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(58));p.topMargin=dp(10);l.addView(b,p);}
}